<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import LibrarySettings from './LibrarySettings.vue'
import AssetBrowser from './AssetBrowser.vue'
import MidiSettings from './MidiSettings.vue'
import BusSettings from './BusSettings.vue'
import ThemePicker from './ThemePicker.vue'
import {state,shared,putShared,attempt,replace} from '../store'
import {clone,factory} from '../model'
import {request,native} from '../native/bridge'
import {themeId} from '../theme/current'
import {themeById} from '../theme/themes'
const sections=[{id:'libraries',name:'Pattern libraries'},{id:'sounds',name:'Sounds'},{id:'playback',name:'Playback'},{id:'midi',name:'MIDI & controllers'},{id:'appearance',name:'Appearance'},{id:'database',name:'Storage & database'},{id:'defaults',name:'Defaults'}]
const section=computed(()=>sections.find(one=>one.id===state.settingsSection)??sections[0]!)
const statistics=ref<{directory:string;databases:{name:string;path:string;bytes:number}[];sounds:number;soundBytes:number;patterns:number;shared:{fields:number;patches:number}}>()
const busy=ref(false),themeSaving=ref(false)
const grids=[{name:'Immediate',value:0},{name:'1/32',value:.125},{name:'1/16',value:.25},{name:'1/8',value:.5},{name:'1/4',value:1},{name:'Bar',value:4}]
let disposed=false
function bytes(value:number){if(value<1024)return `${value} B`;if(value<1024**2)return `${(value/1024).toFixed(1)} KB`;return `${(value/1024**2).toFixed(1)} MB`}
async function refresh(){if(!native()||busy.value)return;busy.value=true;try{const value=await request<typeof statistics.value>('systemStatus');if(!disposed)statistics.value=value}finally{busy.value=false}}
async function setTheme(id:string){if(themeSaving.value)return;const before=themeId.value;themeSaving.value=true;themeId.value=id;try{if(!await putShared('ui/theme',id))themeId.value=themeById(String(shared['ui/theme']?.value??before)).id}catch(error){themeId.value=before;throw error}finally{themeSaving.value=false}}
async function relink(note:number){
 const before=state.patch,key=before.keys.find(key=>key.note===note);if(!key)return
 const sound=key.sound,old=sound.path,path=await request<string|null>('relinkSound')
 if(!path||disposed)return
 if(state.patch!==before||key.sound!==sound||sound.path!==old)throw Error('The instrument changed while locating the sound. Try again.')
 sound.path=path;delete sound.asset;delete sound.missing
}
watch(()=>state.settingsSection,section=>{if(section==='database')void attempt(refresh)})
onMounted(()=>{if(state.settingsSection==='database')void attempt(refresh)})
onBeforeUnmount(()=>{disposed=true})
</script>
<template><section class="settings-workspace workspace-ui">
 <nav class="settings-navigation" aria-label="Settings categories"><strong>SETTINGS</strong><button v-for="item in sections" :key="item.id" :class="{active:section.id===item.id}" :aria-current="section.id===item.id?'page':undefined" @click="state.settingsSection=item.id">{{item.name}}</button></nav>
 <div class="settings-content" :class="{'sound-settings':section.id==='sounds'}"><header class="settings-heading"><h2>{{section.name}}</h2></header>
  <LibrarySettings v-if="section.id==='libraries'"/>
  <template v-else-if="section.id==='sounds'"><details class="assigned-sounds"><summary>Assigned sounds · {{state.patch.keys.length}}</summary><div v-for="key in state.patch.keys" :key="key.note" class="sound-reference"><strong>{{key.name}}</strong><span :title="key.sound.path">{{key.sound.missing?'Missing':key.sound.asset?'Cached':key.sound.path.startsWith('factory:')?'Factory':key.sound.path}}</span><button v-if="key.sound.missing" @click="attempt(()=>relink(key.note))">Locate sound…</button></div></details><AssetBrowser/></template>
  <section v-else-if="section.id==='playback'" class="settings-form"><div class="setting-row"><label>Kit level</label><input v-model.number="state.patch.volume" type="number" min="0" max="1.5" step=".01" aria-label="Kit level"/></div><div v-if="state.standalone" class="setting-row"><label>Tempo</label><input v-model.number="state.patch.bpm" type="number" min="20" max="400" aria-label="Internal tempo"/></div><div class="setting-row"><label>Pattern launch</label><select v-model.number="state.patch.launchGrid" aria-label="Pattern launch quantization"><option v-for="grid in grids" :key="grid.value" :value="grid.value">{{grid.name}}</option></select></div><div class="setting-row"><label>Zone change</label><select v-model.number="state.patch.switchGrid" aria-label="Zone change quantization"><option v-for="grid in grids" :key="grid.value" :value="grid.value">{{grid.name}}</option></select></div><div class="setting-row"><label>Key release</label><select v-model="state.patch.hardRelease" aria-label="Key release behavior"><option :value="false">Let tails ring</option><option :value="true">Stop voices</option></select></div><BusSettings/></section>
  <MidiSettings v-else-if="section.id==='midi'"/>
  <ThemePicker v-else-if="section.id==='appearance'" inline :model-value="true" :busy="themeSaving" @select="id=>attempt(()=>setTheme(id))"/>
  <section v-else-if="section.id==='database'" class="storage-settings"><div class="settings-actions"><button :disabled="busy||!native()" @click="attempt(refresh)">{{busy?'Refreshing…':'Refresh statistics'}}</button></div><template v-if="statistics"><div class="storage-metrics"><div><b>{{statistics.patterns.toLocaleString()}}</b><span>Indexed patterns</span></div><div><b>{{statistics.shared?.patches??0}}</b><span>Saved patches</span></div><div><b>{{statistics.sounds}}</b><span>Cached sounds</span></div><div><b>{{bytes(statistics.soundBytes)}}</b><span>Sound cache</span></div></div><h3>Databases</h3><div v-for="database in statistics.databases" :key="database.name" class="database-row"><span>{{database.name}}</span><b>{{bytes(database.bytes)}}</b></div><p class="settings-path">{{statistics.directory}}</p><p class="settings-hint">{{statistics.shared?.fields??0}} shared settings and library entries</p></template><p v-else class="settings-hint">{{native()?'Refresh to read storage statistics.':'Storage statistics are available in the native instrument.'}}</p></section>
  <section v-else-if="section.id==='defaults'" class="defaults-settings"><h3>Restore the factory instrument</h3><p>Replace the current instrument with the Circuit kit. Saved patches and imported libraries are kept. Undo is available.</p><button @click="attempt(()=>replace(clone(factory())))">Restore factory defaults</button></section>
 </div>
</section></template>
<style scoped>
.settings-workspace{height:100%;min-height:0;display:grid;grid-template-columns:185px minmax(0,1fr);border:1px solid var(--line);border-radius:4px;overflow:hidden;background:var(--panel-lo)}.settings-navigation{display:flex;flex-direction:column;gap:2px;padding:8px;border-right:1px solid var(--line);background:#0002;overflow:auto}.settings-navigation>strong{font-size:9px;letter-spacing:.14em;color:var(--text-mute);padding:2px 8px 8px}.settings-navigation button{text-align:left;padding:4px 8px!important;border-color:transparent!important;background:transparent!important;font-size:11px!important;flex:none}.settings-navigation button.active{background:#ffffff0c!important;color:var(--c-primary)!important;border-color:var(--line)!important}.settings-content{min-height:0;overflow:auto;padding:12px 16px;display:flex;flex-direction:column;gap:12px}.settings-heading{border-bottom:1px solid var(--line);padding-bottom:8px;flex:none}.settings-heading h2{font-size:16px;font-weight:500;margin:0}.settings-content h3{font-size:13px;font-weight:500;margin:0 0 12px}.settings-form{max-width:550px}.setting-row{display:flex;align-items:center;gap:20px;padding:11px 0;border-bottom:1px solid color-mix(in srgb,var(--line) 45%,transparent)}.setting-row label{width:150px;font-size:12px}.setting-row input,.setting-row select{width:170px}.assigned-sounds{flex:none;font-size:12px}.assigned-sounds summary{cursor:pointer;color:var(--text-dim);padding-bottom:8px}.sound-reference{display:flex;align-items:center;gap:12px;padding:6px 0;border-bottom:1px solid var(--line);font-size:11px}.sound-reference strong{min-width:110px;font-weight:500}.sound-reference span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-dim)}.sound-settings{overflow:hidden;gap:8px}.sound-settings>.asset-browser{flex:1;min-height:0;height:auto}.sound-settings :deep(.browser-body){min-height:0}.sound-settings :deep(.browser-tools){gap:5px;margin-bottom:7px}.sound-settings :deep(.browser-footer){height:22px;flex:none;font-size:9px}.assigned-sounds[open]{max-height:120px;overflow:auto}.storage-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin:18px 0 24px}.storage-metrics>div{padding:16px 12px;background:#0002;border:1px solid var(--line);display:grid;gap:7px}.storage-metrics b{font-size:20px;font-weight:500;color:var(--text-head)}.storage-metrics span{font-size:10px;color:var(--text-mute)}.database-row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);font-size:12px}.database-row b{font-weight:500}.settings-path{overflow-wrap:anywhere;font:11px monospace;color:var(--text-mute);margin:18px 0 5px}.defaults-settings{max-width:550px}.defaults-settings p{font-size:12px;color:var(--text-dim);line-height:1.7;margin-bottom:20px}.settings-content :deep(.picker){width:100%;max-height:none;box-shadow:none;border:0;background:none}.settings-content :deep(.picker .head){padding:0 0 12px}.settings-content :deep(.picker .body){padding:0;overflow:visible}@media(max-width:850px){.settings-workspace{grid-template-columns:150px minmax(0,1fr)}.settings-content{padding:14px}.settings-navigation button{font-size:11px!important}.storage-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
